def metric(data: pd.DataFrame) -> float:
    ttb_matches = 0
    total = 0
    for a, b, r in zip(data['option_a_ratings'], data['option_b_ratings'], data['response']):
        for i in range(5):
            if a[i] > b[i]:
                if r == 0:
                    ttb_matches += 1
                break
            elif b[i] > a[i]:
                if r == 1:
                    ttb_matches += 1
                break
        total += 1
    return float(ttb_matches / total) if total > 0 else 0.0

